window.IPM_TIER_EXPANSION.qc_01 = [
  { level: "Foundation", problem: "4. Express 37.5% as a simplified fraction and find 37.5% of 640.", steps: ["37.5% = 3/8.", "3/8 * 640 = 3 * 80 = 240."] },
  { level: "Foundation", problem: "5. A shirt marked at Rs. 1,200 is sold for Rs. 960. Find the discount percentage.", steps: ["Discount = 1200 - 960 = Rs. 240.", "Discount % = (240 / 1200) * 100 = 20%."] },
  { level: "Foundation", problem: "6. Find Simple Interest on Rs. 7,500 at 8% p.a. for 3 years 6 months.", steps: ["Time = 3.5 years.", "SI = (7500 * 8 * 3.5) / 100 = Rs. 2,100."] },
  { level: "Foundation", problem: "7. If CP of 15 articles equals SP of 12 articles, find profit percentage.", steps: ["SP / CP = 15 / 12 = 5 / 4 = 1.25.", "Profit % = 25%."] },
  { level: "Foundation", problem: "8. A salary of Rs. 40,000 is raised by 15%. Find the new salary.", steps: ["New Salary = 40,000 * 1.15 = Rs. 46,000."] },
  { level: "Foundation", problem: "9. Convert a profit margin of 20% on Selling Price into profit % on Cost Price.", steps: ["SP = 100, Profit = 20 => CP = 80.", "Profit on CP = (20 / 80) * 100 = 25%."] },
  { level: "Foundation", problem: "10. Find Compound Interest on Rs. 10,000 at 10% p.a. for 2 years compounded annually.", steps: ["Effective 2-yr CI rate = 10 + 10 + 1 = 21%.", "CI = 21% of 10,000 = Rs. 2,100."] },
  { level: "GRE General Moderate", problem: "8. A retailer offers 'Buy 5 Get 3 Free' plus an additional 10% cash discount. Find the effective discount %.", steps: ["Free item discount = 3 / (5 + 3) = 3/8 = 37.5% (factor 0.625).", "Net factor = 0.625 * 0.90 = 0.5625 => Effective Discount = (1 - 0.5625)*100 = 43.75%."] },
  { level: "GRE General Moderate", problem: "9. Two successive price hikes of 20% and x% result in an overall increase of 50%. Find x.", steps: ["1.20 * (1 + x/100) = 1.50 => 1 + x/100 = 1.25 => x = 25%."] },
  { level: "GRE General Moderate", problem: "10. A sum doubles at SI in 8 years. In how many years will it become 5 times itself at the same rate?", steps: ["To gain 100% (double) takes 8 yrs => Rate = 12.5%.", "To gain 400% (5x) takes 4 * 8 = 32 years."] },
  { level: "GRE General Moderate", problem: "11. If the price of sugar falls by 20%, a buyer gets 5 kg more for Rs. 400. Find the original price per kg.", steps: ["20% of Rs. 400 = Rs. 80 buys 5 kg => New price = 80/5 = Rs. 16/kg.", "Original price = 16 / 0.80 = Rs. 20/kg."] },
  { level: "GRE General Moderate", problem: "12. Find the difference between CI compounded half-yearly and yearly on Rs. 20,000 at 10% p.a. for 1 year.", steps: ["Yearly CI = 10%; Half-yearly CI = 5% + 5% + 0.25% = 10.25%.", "Difference = 0.25% of 20,000 = Rs. 50."] },
  { level: "GRE General Moderate", problem: "13. An article sold at Rs. 1,440 yields a profit equal to twice the loss incurred when sold at Rs. 1,080. Find CP.", steps: ["1440 - CP = 2 * (CP - 1080) => 3 * CP = 1440 + 2160 = 3600 => CP = Rs. 1,200."] },
  { level: "IIM Tough", problem: "11. The difference between CI and SI for 3 years at 10% p.a. is Rs. 620. Find the principal.", steps: ["CI - SI (3 yrs) = P * (0.10)^2 * (3 + 0.10) = P * 0.01 * 3.1 = 0.031 * P.", "0.031 * P = 620 => P = Rs. 20,000."] },
  { level: "IIM Tough", problem: "12. A loan of Rs. 21,000 is repaid in two equal annual installments at 10% p.a. CI. Find each installment.", steps: ["Installment X: X/1.1 + X/(1.1)^2 = 21,000 => X * (11 + 10)/121 = 21,000.", "X = (21,000 * 121) / 21 = Rs. 12,100."] },
  { level: "IIM Tough", problem: "13. A vendor mixes two teas at Rs. 180/kg and Rs. 240/kg in ratio 3:2 and sells at Rs. 235.20/kg. Find profit %.", steps: ["Avg CP = (3*180 + 2*240)/5 = 1020/5 = Rs. 204/kg.", "Profit % = [(235.20 - 204) / 204] * 100 = (31.2 / 204)*100 = 15.29%."] },
  { level: "IIM Tough", problem: "14. In an exam, A got 20% more than B, B got 25% less than C, and C got 20% more than D. If D got 500, find A's score.", steps: ["C = 500 * 1.20 = 600; B = 600 * 0.75 = 450; A = 450 * 1.20 = 540."] },
  { level: "IIM Tough", problem: "15. A merchant marks up by 40% and gives a discount of d%, still making 12% profit. If he gave 2d% discount, find his profit/loss %.", steps: ["1.40 * (1 - d/100) = 1.12 => 1 - d/100 = 0.80 => d = 20%.", "With 2d = 40% discount: SP/CP = 1.40 * 0.60 = 0.84 => 16% loss."] },
  { level: "IIM Tough", problem: "16. Population grows 10% in Yr 1, 20% in Yr 2, and drops 25% in Yr 3. Find net % change over 3 years.", steps: ["Net factor = 1.10 * 1.20 * 0.75 = 1.32 * 0.75 = 0.99 => 1% net decrease."] },
  { level: "IIM Tough", problem: "17. [Indore SA] A sphere's radius increases by 10%. By what exact % does its volume increase?", steps: ["Volume scales as r^3: (1.10)^3 = 1.331 => 33.1% increase."] }
];

